module max_flow_network (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] num_suppliers,\n    input wire [3:0] num_factories,\n    input wire [3:0] num_companies,\n    input wire [3:0] supplier_states [0:7],\n    input wire [3:0] factory_states [0:7],\n    input wire [3:0] company_states [0:7][0:7],\n    output reg [7:0] max_flow,\n    output reg done\n);\n\n// Internal parameters\nlocalparam NODE_SOURCE = 0;\nlocalparam NODE_SINK = 1;\nlocalparam NODE_SUPPLIERS_START = 2;\nlocalparam NODE_FACTORIES_START = 10;\nlocalparam NODE_COMPANIES_START = 18;\nlocalparam MAX_NODES = 26;\nlocalparam INVALID_NODE = 63;\n\n// Capacity and flow matrices\nreg [7:0] capacity [0:MAX_NODES-1][0:MAX_NODES-1];\nreg [7:0] flow [0:MAX_NODES-1][0:MAX_NODES-1];\n\n// BFS variables\nreg [5:0] parent [0:MAX_NODES-1];\nreg [5:0] queue [0:MAX_NODES-1];\nreg visited [0:MAX_NODES-1];\nreg [5:0] queue_head, queue_tail;\n\n// Algorithm state\nlocalparam [3:0] S_IDLE = 4'd0;\nlocalparam [3:0] S_BUILD_NETWORK = 4'd1;\nlocalparam [3:0] S_BFS_INIT = 4'd2;\nlocalparam [3:0] S_BFS_PROCESS = 4'd3;\nlocalparam [3:0] S_UPDATE_FLOW = 4'd4;\nlocalparam [3:0] S_CHECK_DONE = 4'd5;\nlocalparam [3:0] S_FINISH = 4'd6;\nreg [3:0] state;\n\n// Loop counters\nreg [5:0] u, v;\nreg [3:0] i, j, k, m;\nreg [7:0] path_flow;\nreg [7:0] max_flow_reg;\n\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= S_IDLE;\n        done <= 1'b0;\n        max_flow <= 8'd0;\n        max_flow_reg <= 8'd0;\n        \n        for (i = 0; i < MAX_NODES; i = i + 1) begin\n            visited[i] <= 1'b0;\n            parent[i] <= INVALID_NODE;\n            queue[i] <= 6'd0;\n            for (j = 0; j < MAX_NODES; j = j + 1) begin\n                capacity[i][j] <= 8'd0;\n                flow[i][j] <= 8'd0;\n            end\n        end\n    end else begin\n        case (state)\n            S_IDLE: begin\n                done <= 1'b0;\n                if (start) begin\n                    state <= S_BUILD_NETWORK;\n                    max_flow_reg <= 8'd0;\n                end\n            end\n            \n            S_BUILD_NETWORK: begin\n                // Clear capacities\n                for (i = 0; i < MAX_NODES; i = i + 1) begin\n                    for (j = 0; j < MAX_NODES; j = j + 1) begin\n                        capacity[i][j] <= 8'd0;\n                    end\n                end\n                \n                // Connect SOURCE -> Suppliers\n                for (i = 0; i < 8; i = i + 1) begin\n                    capacity[NODE_SOURCE][NODE_SUPPLIERS_START + i] <= (i < num_suppliers) ? 8'd1 : 8'd0;\n                end\n                \n                // Connect Factories -> SINK\n                for (i = 0; i < 8; i = i + 1) begin\n                    capacity[NODE_FACTORIES_START + i][NODE_SINK] <= (i < num_factories) ? 8'd1 : 8'd0;\n                end\n                \n                // Supplier->Company edges\n                for (i = 0; i < 8; i = i + 1) begin\n                    if (i < num_suppliers) begin\n                        for (j = 0; j < 8; j = j + 1) begin\n                            if (j < num_companies) begin\n                                for (k = 0; k < 8; k = k + 1) begin\n                                    if (company_states[j][k] == supplier_states[i] && company_states[j][k] != 4'hF) begin\n                                        capacity[NODE_SUPPLIERS_START + i][NODE_COMPANIES_START + j] <= 8'd1;\n                                    end\n                                end\n                            end\n                        end\n                    end\n                end\n                \n                // Company->Factory edges\n                for (i = 0; i < 8; i = i + 1) begin\n                    if (i < num_companies) begin\n                        for (j = 0; j < 8; j = j + 1) begin\n                            if (j < num_factories) begin\n                                for (k = 0; k < 8; k = k + 1) begin\n                                    if (company_states[i][k] == factory_states[j] && company_states[i][k] != 4'hF) begin\n                                        capacity[NODE_COMPANIES_START + i][NODE_FACTORIES_START + j] <= 8'd1;\n                                    end\n                                end\n                            end\n                        end\n                    end\n                end\n                \n                // Company->Company edges\n                for (i = 0; i < 8; i = i + 1) begin\n                    if (i < num_companies) begin\n                        for (j = 0; j < 8; j = j + 1) begin\n                            if (j < num_companies && i != j) begin\n                                for (k = 0; k < 8; k = k + 1) begin\n                                    if (company_states[i][k] != 4'hF) begin\n                                        for (m = 0; m < 8; m = m + 1) begin\n                                            if (company_states[j][m] == company_states[i][k] && company_states[j][m] != 4'hF) begin\n                                                capacity[NODE_COMPANIES_START + i][NODE_COMPANIES_START + j] <= 8'd1;\n                                            end\n                                        end\n                                    end\n                                end\n                            end\n                        end\n                    end\n                end\n                \n                state <= S_BFS_INIT;\n            end\n            \n            S_BFS_INIT: begin\n                for (i = 0; i < MAX_NODES; i = i + 1) begin\n                    visited[i] <= 1'b0;\n                    parent[i] <= INVALID_NODE;\n                    queue[i] <= 6'd0;\n                end\n                queue_head <= 6'd0;\n                queue_tail <= 6'd1;\n                queue[0] <= NODE_SOURCE;\n                visited[NODE_SOURCE] <= 1'b1;\n                j <= 6'd0;\n                state <= S_BFS_PROCESS;\n            end\n            \n            S_BFS_PROCESS: begin\n                if (queue_head < queue_tail) begin\n                    u <= queue[queue_head];\n                    queue_head <= queue_head + 6'd1;\n                    j <= 6'd0;\n                    state <= 4'd7;  // BFS LOOP STATE\n                end else begin\n                    if (parent[NODE_SINK] != INVALID_NODE) begin\n                        state <= S_UPDATE_FLOW;\n                    end else begin\n                        state <= S_CHECK_DONE;\n                    end\n                end\n            end\n            \n            4'd7: begin  // BFS neighbor check\n                if (j < MAX_NODES) begin\n                    if (capacity[u][j] > flow[u][j] && !visited[j]) begin\n                        queue[queue_tail] <= j;\n                        queue_tail <= queue_tail + 6'd1;\n                        parent[j] <= u;\n                        visited[j] <= 1'b1;\n                    end\n                    j <= j + 6'd1;\n                end else begin\n                    state <= S_BFS_PROCESS;\n                end\n            end\n            \n            S_UPDATE_FLOW: begin\n                path_flow <= 8'd255;\n                v <= NODE_SINK;\n                state <= 4'd8;  // Find path_flow\n            end\n            \n            4'd8: begin\n                if (v != NODE_SOURCE) begin\n                    u <= parent[v];\n                    if (capacity[u][v] - flow[u][v] < path_flow) begin\n                        path_flow <= capacity[u][v] - flow[u][v];\n                    end\n                    v <= parent[v];\n                end else begin\n                    v <= NODE_SINK;\n                    state <= 4'd9;  // Update flow\n                end\n            end\n            \n            4'd9: begin\n                if (v != NODE_SOURCE) begin\n                    u <= parent[v];\n                    flow[u][v] <= flow[u][v] + path_flow;\n                    flow[v][u] <= flow[v][u] - path_flow;\n                    v <= parent[v];\n                end else begin\n                    max_flow_reg <= max_flow_reg + path_flow;\n                    state <= S_BFS_INIT;\n                end\n            end\n            \n            S_CHECK_DONE: begin\n                max_flow <= max_flow_reg;\n                state <= S_FINISH;\n            end\n            \n            S_FINISH: begin\n                done <= 1'b1;\n                state <= S_IDLE;\n            end\n            \n            default: state <= S_IDLE;\n        endcase\n    end\nend\n\nendmodule